                bool ienumRecv =
                    recvTy && recvTy->kind == TypeRef::Kind::Named &&
                    !recvTy->genericArgs.empty() && recvTy->astNode &&
                    recvTy->astNode->name &&
                    !recvTy->astNode->name->parts.empty() &&
                    recvTy->headName() == "IEnumerable";
